-- youB — Bee Action Authorization + Impact Model V1 structural and hardening suite
-- Disposable staging only. Transactional fixtures, fail-fast assertions, no migration execution.
begin;
create temp table ctx(key text primary key, value uuid not null) on commit drop;
do $$ declare k text; begin
  foreach k in array array['bee_action_requests','intelligence_outcome_evidence'] loop
    if to_regclass('public.'||k) is null then raise exception 'missing Bee/Impact prerequisite: %', k; end if;
  end loop;
  if (select count(*) from auth.users) < 5 then raise exception 'suite requires five auth users'; end if;
end $$;
insert into ctx values
 ('org_a','11111111-1111-1111-1111-111111111111'),('org_b','22222222-2222-2222-2222-222222222222'),
 ('employee_a','11111111-0000-0000-0000-000000000001'),('employee_b','22222222-0000-0000-0000-000000000001'),
 ('recommendation_a','11111111-0000-0000-0000-000000000010'),('intervention_a','11111111-0000-0000-0000-000000000011'),
 ('action_a','11111111-0000-0000-0000-000000000012'),('outcome_a','11111111-0000-0000-0000-000000000013'),('outcome_b','22222222-0000-0000-0000-000000000013'),('outcome_b_probe','22222222-0000-0000-0000-000000000019'),
 ('signal_a','11111111-0000-0000-0000-000000000014'),('signal_b','22222222-0000-0000-0000-000000000014'),('signal_b_probe','22222222-0000-0000-0000-000000000017'),('evidence_a','11111111-0000-0000-0000-000000000015'),('evidence_b','22222222-0000-0000-0000-000000000015'),('evidence_b_probe','22222222-0000-0000-0000-000000000018'),('evidence_contradicts','11111111-0000-0000-0000-000000000016'),
 ('bee_private','11111111-0000-0000-0000-000000000020'),('bee_other','11111111-0000-0000-0000-000000000021');
insert into ctx select 'user_'||row_number() over(order by created_at),id from auth.users order by created_at limit 5;
insert into public.organizations(id,name,slug,plan,status) values ((select value from ctx where key='org_a'),'Bee Impact A','bee-impact-a','essencial','active'),((select value from ctx where key='org_b'),'Bee Impact B','bee-impact-b','essencial','active');
insert into public.memberships(organization_id,user_id,role) values ((select value from ctx where key='org_a'),(select value from ctx where key='user_1'),'admin_youb'),((select value from ctx where key='org_a'),(select value from ctx where key='user_2'),'diretoria'),((select value from ctx where key='org_a'),(select value from ctx where key='user_3'),'gestor'),((select value from ctx where key='org_a'),(select value from ctx where key='user_4'),'colaborador'),((select value from ctx where key='org_a'),(select value from ctx where key='user_5'),'rh');
insert into public.employees(id,organization_id,auth_user_id,full_name,email,manager_employee_id) values ((select value from ctx where key='employee_a'),(select value from ctx where key='org_a'),null,'Bee Employee A','bee-a@example.invalid',null),((select value from ctx where key='employee_b'),(select value from ctx where key='org_b'),null,'Bee Employee B','bee-b@example.invalid',null);
insert into public.intelligence_signals(id,organization_id,employee_id,signal_type,source_type) values ((select value from ctx where key='signal_a'),(select value from ctx where key='org_a'),(select value from ctx where key='employee_a'),'fixture','test'),((select value from ctx where key='signal_b'),(select value from ctx where key='org_b'),(select value from ctx where key='employee_b'),'fixture','test'),((select value from ctx where key='signal_b_probe'),(select value from ctx where key='org_b'),(select value from ctx where key='employee_b'),'fixture_probe','test');
insert into public.intelligence_evidence(id,organization_id,signal_id,evidence_type,summary,relation,independence_group,source_type) values ((select value from ctx where key='evidence_a'),(select value from ctx where key='org_a'),(select value from ctx where key='signal_a'),'documented','fixture','supports','bee-source','test'),((select value from ctx where key='evidence_contradicts'),(select value from ctx where key='org_a'),(select value from ctx where key='signal_a'),'qualitative','contradictory fixture','contradicts','independent-source','test'),((select value from ctx where key='evidence_b'),(select value from ctx where key='org_b'),(select value from ctx where key='signal_b'),'documented','tenant B fixture','supports','bee-source','test'),((select value from ctx where key='evidence_b_probe'),(select value from ctx where key='org_b'),(select value from ctx where key='signal_b_probe'),'documented','tenant B RLS probe evidence','supports','probe-source','test');
insert into public.intelligence_recommendations(id,organization_id,employee_id,title) values ((select value from ctx where key='recommendation_a'),(select value from ctx where key='org_a'),(select value from ctx where key='employee_a'),'Bee fixture recommendation');
insert into public.intelligence_interventions(id,organization_id,recommendation_id,employee_id,intervention_type,title) values ((select value from ctx where key='intervention_a'),(select value from ctx where key='org_a'),(select value from ctx where key='recommendation_a'),(select value from ctx where key='employee_a'),'fixture','Bee fixture intervention');
insert into public.intelligence_actions(id,organization_id,intervention_id,action_type,title,assignee_employee_id) values ((select value from ctx where key='action_a'),(select value from ctx where key='org_a'),(select value from ctx where key='intervention_a'),'fixture','Bee fixture action',(select value from ctx where key='employee_a'));
insert into public.intelligence_outcomes(id,organization_id,intervention_id,action_id,outcome_type) values ((select value from ctx where key='outcome_a'),(select value from ctx where key='org_a'),(select value from ctx where key='intervention_a'),(select value from ctx where key='action_a'),'fixture'),((select value from ctx where key='outcome_b'),(select value from ctx where key='org_b'),null,null,'tenant_b_fixture'),((select value from ctx where key='outcome_b_probe'),(select value from ctx where key='org_b'),null,null,'tenant_b_rls_probe');
