insert into public.bee_action_requests(id,organization_id,requester_user_id,action_key,capability_level,risk_level,authorization_requirement,authorization_status,purpose,target_scope_type,request_payload,execution_payload,execution_result) values ((select value from ctx where key='bee_private'),(select value from ctx where key='org_a'),(select value from ctx where key='user_4'),'private_context','explain','informational','none','not_required','Private collaborator context','employee','{}','{}','{}'),((select value from ctx where key='bee_other'),(select value from ctx where key='org_a'),(select value from ctx where key='user_1'),'admin_context','explain','informational','none','not_required','Admin context','organization','{}','{}','{}');

create or replace function pg_temp.assert_true(label text, condition boolean) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'FAIL-FAST assertion: %',label; end if; end; $$;
create or replace function pg_temp.try_bee(p_cap text,p_risk text,p_req text,p_auth text,p_exec text,p_scope text,p_sensitivity text,p_confirmed_by uuid,p_confirmed_at timestamptz,p_approved_by uuid,p_approved_at timestamptz,p_executed_at timestamptz) returns boolean language plpgsql security invoker as $$ declare probe uuid; begin begin insert into public.bee_action_requests(organization_id,requester_user_id,requester_employee_id,action_key,capability_level,risk_level,authorization_requirement,authorization_status,execution_status,purpose,target_scope_type,target_scope_ref,target_employee_id,sensitivity,confirmed_by,confirmed_at,approved_by,approved_at,executed_at) values((select value from ctx where key='org_a'),(select value from ctx where key='user_1'),(select value from ctx where key='employee_a'),'qa_'||md5(random()::text),p_cap,p_risk,p_req,p_auth,p_exec,'QA request',p_scope,'descriptive-ref',(select value from ctx where key='employee_a'),p_sensitivity,p_confirmed_by,p_confirmed_at,p_approved_by,p_approved_at,p_executed_at) returning id into probe; delete from public.bee_action_requests where id=probe; return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_outcome(p_level text,p_claim text,p_measure text,p_validation text,p_financial numeric,p_currency text,p_method text,p_validated_by uuid,p_validated_at timestamptz) returns boolean language plpgsql security invoker as $$ declare probe uuid; begin begin insert into public.intelligence_outcomes(organization_id,outcome_type,outcome_level,claim_strength,measurement_kind,validation_status,financial_value,currency,measurement_methodology,validated_by,validated_at,context) values((select value from ctx where key='org_a'),'qa_probe',p_level,p_claim,p_measure,p_validation,p_financial,p_currency,p_method,p_validated_by,p_validated_at,'{}') returning id into probe; delete from public.intelligence_outcomes where id=probe; return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.invalid_bee_json_shape() returns boolean language plpgsql security invoker as $$ begin begin insert into public.bee_action_requests(organization_id,requester_user_id,action_key,capability_level,risk_level,authorization_requirement,authorization_status,purpose,target_scope_type,request_payload) values((select value from ctx where key='org_a'),(select value from ctx where key='user_1'),'invalid_json','observe','informational','none','not_required','QA invalid JSON','employee','[]'); return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.outcome_rls_probe() returns boolean language plpgsql security invoker as $$ declare msg text; begin begin insert into public.intelligence_outcomes(organization_id,outcome_type,outcome_level,claim_strength,measurement_kind,validation_status,metric_key,metric_label,metric_unit,observed_value,window_start,window_end,context) values((select value from ctx where key='org_b'),'valid_org_b_probe','business','observed','measured','reviewed','qa_metric','QA Metric','count',1,'2026-09-01','2026-09-02','{}'); return false; exception when others then get stacked diagnostics msg = message_text; return msg ilike '%row-level security%'; end; end; $$;
create or replace function pg_temp.outcome_evidence_rls_probe() returns boolean language plpgsql security invoker as $$ declare msg text; begin begin insert into public.intelligence_outcome_evidence(organization_id,outcome_id,evidence_id,relation) values((select value from ctx where key='org_b'),(select value from ctx where key='outcome_b_probe'),(select value from ctx where key='evidence_b_probe'),'supports'); return false; exception when others then get stacked diagnostics msg = message_text; return msg ilike '%row-level security%'; end; end; $$;
create or replace function pg_temp.outcome_evidence_fk_probe() returns boolean language plpgsql security invoker as $$ declare msg text; begin begin insert into public.intelligence_outcome_evidence(organization_id,outcome_id,evidence_id,relation) values((select value from ctx where key='org_a'),(select value from ctx where key='outcome_a'),(select value from ctx where key='evidence_b'),'supports'); return false; exception when others then get stacked diagnostics msg = message_text; return msg ilike '%foreign key%' or msg ilike '%violates%'; end; end; $$;
create or replace function pg_temp.cross_tenant_bee_rls_probe() returns boolean language plpgsql security invoker as $$ declare msg text; begin begin insert into public.bee_action_requests(organization_id,requester_user_id,requester_employee_id,action_key,capability_level,risk_level,authorization_requirement,authorization_status,purpose,target_scope_type,target_employee_id,request_payload,execution_payload,execution_result) values((select value from ctx where key='org_b'),(select value from ctx where key='user_1'),'22222222-0000-0000-0000-000000000001','tenant_b_action','explain','informational','none','not_required','Valid tenant B request','employee','22222222-0000-0000-0000-000000000001','{}','{}','{}'); return false; exception when others then get stacked diagnostics msg = message_text; return msg ilike '%row-level security%'; end; end; $$;

create or replace function pg_temp.rh_valid_bee_request() returns boolean language plpgsql security invoker as $$ declare probe uuid; begin begin insert into public.bee_action_requests(organization_id,requester_user_id,requester_employee_id,action_key,capability_level,risk_level,authorization_requirement,authorization_status,execution_status,purpose,target_scope_type,target_scope_ref,target_employee_id,sensitivity,request_payload,execution_payload,execution_result) values((select value from ctx where key='org_a'),(select value from ctx where key='user_5'),(select value from ctx where key='employee_a'),'rh_qa_action','explain','informational','none','not_required','not_started','RH QA request','employee','rh-qa-ref',(select value from ctx where key='employee_a'),'standard','{}','{}','{}') returning id into probe; delete from public.bee_action_requests where id=probe; return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.rh_valid_outcome() returns boolean language plpgsql security invoker as $$ declare probe uuid; begin begin insert into public.intelligence_outcomes(organization_id,outcome_type,status,details,measured_at,outcome_level,claim_strength,measurement_kind,validation_status,metric_key,metric_label,metric_unit,observed_value,window_start,window_end,context) values((select value from ctx where key='org_a'),'rh_qa_outcome','observed','{}',now(),'business','observed','measured','reviewed','rh_metric','RH QA Metric','count',1,'2026-09-01','2026-09-02','{}') returning id into probe; delete from public.intelligence_outcomes where id=probe; return true; exception when others then return false; end; end; $$;

set local role authenticated;
select set_config('request.jwt.claim.sub',(select value::text from ctx where key='user_1'),true);
-- Every Bee vocabulary: valid values and invalid values, independently asserted.
select pg_temp.assert_true('capability observe valid',pg_temp.try_bee('observe','informational','none','not_required','not_started','employee','standard',null,null,null,null,null));
