select pg_temp.assert_true('invalid scope rejected',not pg_temp.try_bee('observe','informational','none','not_required','not_started','invalid','standard',null,null,null,null,null));
select pg_temp.assert_true('sensitivity standard valid',pg_temp.try_bee('observe','informational','none','not_required','not_started','employee','standard',null,null,null,null,null));
