select pg_temp.assert_true('status awaiting_confirmation valid',pg_temp.try_bee('ask','personal_reversible','confirmation','awaiting_confirmation','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('status awaiting_approval valid',pg_temp.try_bee('prepare','operational','approval','awaiting_approval','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('status approved valid with provenance',pg_temp.try_bee('ask','personal_reversible','confirmation','approved','not_started','employee','standard',(select value from ctx where key='user_1'),now(),null,null,null));
select pg_temp.assert_true('status rejected valid',pg_temp.try_bee('ask','personal_reversible','confirmation','rejected','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('status expired valid',pg_temp.try_bee('prepare','operational','approval','expired','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('invalid authorization status rejected',not pg_temp.try_bee('observe','informational','none','invalid','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('execution not_started valid',pg_temp.try_bee('observe','informational','none','not_required','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('execution ready valid after confirmation approval',pg_temp.try_bee('ask','personal_reversible','confirmation','approved','ready','employee','standard',(select value from ctx where key='user_1'),now(),null,null,null));
select pg_temp.assert_true('execution executing valid after approval',pg_temp.try_bee('prepare','operational','approval','approved','executing','employee','standard',null,null,(select value from ctx where key='user_1'),now(),null));
