select pg_temp.assert_true('invalid execution status rejected',not pg_temp.try_bee('observe','informational','none','not_required','invalid','employee','standard',null,null,null,null,null));
-- State-machine hardening: invalid combinations must fail for both confirmation and approval.
select pg_temp.assert_true('none cannot await confirmation',not pg_temp.try_bee('observe','informational','none','awaiting_confirmation','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('confirmation cannot be not_required',not pg_temp.try_bee('ask','personal_reversible','confirmation','not_required','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('approval cannot await confirmation',not pg_temp.try_bee('prepare','operational','approval','awaiting_confirmation','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('prohibited must be rejected',not pg_temp.try_bee('observe','prohibited_autonomous','prohibited','approved','not_started','employee','standard',null,null,(select value from ctx where key='user_1'),now(),null));
select pg_temp.assert_true('prohibited cannot execute',not pg_temp.try_bee('observe','prohibited_autonomous','prohibited','rejected','ready','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('confirmation approved requires confirmed_by and confirmed_at',not pg_temp.try_bee('ask','personal_reversible','confirmation','approved','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('approval approved requires approved_by and approved_at',not pg_temp.try_bee('prepare','operational','approval','approved','not_started','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('confirmation ready requires approved status',not pg_temp.try_bee('ask','personal_reversible','confirmation','awaiting_confirmation','ready','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('confirmation executing requires approved status',not pg_temp.try_bee('ask','personal_reversible','confirmation','awaiting_confirmation','executing','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('confirmation completed requires approved status',not pg_temp.try_bee('ask','personal_reversible','confirmation','awaiting_confirmation','completed','employee','standard',null,null,null,null,now()));
select pg_temp.assert_true('approval ready requires approved status',not pg_temp.try_bee('prepare','operational','approval','awaiting_approval','ready','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('approval executing requires approved status',not pg_temp.try_bee('prepare','operational','approval','awaiting_approval','executing','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('approval completed requires approved status',not pg_temp.try_bee('prepare','operational','approval','awaiting_approval','completed','employee','standard',null,null,null,null,now()));
select pg_temp.assert_true('rejected cannot be ready',not pg_temp.try_bee('ask','personal_reversible','confirmation','rejected','ready','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('expired cannot be executing',not pg_temp.try_bee('prepare','operational','approval','expired','executing','employee','standard',null,null,null,null,null));
select pg_temp.assert_true('sensitive execute cannot use confirmation only',not pg_temp.try_bee('execute','sensitive','confirmation','approved','not_started','employee','standard',(select value from ctx where key='user_1'),now(),null,null,null));
select pg_temp.assert_true('completed requires executed_at',not pg_temp.try_bee('prepare','operational','approval','approved','completed','employee','standard',null,null,(select value from ctx where key='user_1'),now(),null));
select pg_temp.assert_true('Bee JSON objects required',not pg_temp.invalid_bee_json_shape());
select pg_temp.assert_true('no Bee request creates action or intervention',((select count(*) from public.intelligence_actions where organization_id=(select value from ctx where key='org_a'))=1 and (select count(*) from public.intelligence_interventions where organization_id=(select value from ctx where key='org_a'))=1));

-- Impact vocabularies: every valid value plus invalid values.
select pg_temp.assert_true('outcome execution valid',pg_temp.try_outcome('execution','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('outcome learning valid',pg_temp.try_outcome('learning','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('outcome application valid',pg_temp.try_outcome('application','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('outcome capability valid',pg_temp.try_outcome('capability','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('outcome people valid',pg_temp.try_outcome('people','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('outcome business valid',pg_temp.try_outcome('business','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('outcome financial valid with methodology',pg_temp.try_outcome('financial','associated','estimated','unvalidated',10,'BRL','reviewed methodology',null,null));
select pg_temp.assert_true('invalid outcome level rejected',not pg_temp.try_outcome('invalid','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('claim observed valid',pg_temp.try_outcome('business','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('claim associated valid',pg_temp.try_outcome('business','associated','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('claim contribution_supported valid',pg_temp.try_outcome('business','contribution_supported','measured','reviewed',null,null,null,null,null));
select pg_temp.assert_true('claim causal_validated valid with methodology',pg_temp.try_outcome('business','causal_validated','measured','validated',null,null,'causal methodology',(select value from ctx where key='user_1'),now()));
select pg_temp.assert_true('invalid claim rejected',not pg_temp.try_outcome('business','invalid','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('measurement measured valid',pg_temp.try_outcome('business','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('measurement estimated valid',pg_temp.try_outcome('business','observed','estimated','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('invalid measurement rejected',not pg_temp.try_outcome('business','observed','invalid','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('validation unvalidated valid',pg_temp.try_outcome('business','observed','measured','unvalidated',null,null,null,null,null));
select pg_temp.assert_true('validation reviewed valid',pg_temp.try_outcome('business','observed','measured','reviewed',null,null,null,null,null));
