select pg_temp.assert_true('causal validated requires methodology',not pg_temp.try_outcome('business','causal_validated','measured','validated',null,null,null,(select value from ctx where key='user_1'),now()));
select pg_temp.assert_true('financial value without currency fails',not pg_temp.try_outcome('business','associated','estimated','unvalidated',10,null,'financial methodology',null,null));
select pg_temp.assert_true('financial value without methodology fails',not pg_temp.try_outcome('business','associated','estimated','unvalidated',10,'BRL',null,null,null));
select pg_temp.assert_true('financial negative value fails',not pg_temp.try_outcome('business','associated','estimated','unvalidated',-1,'BRL','financial methodology',null,null));
select pg_temp.assert_true('financial value with currency and methodology succeeds',pg_temp.try_outcome('business','associated','estimated','unvalidated',10,'BRL','financial methodology',null,null));

-- Direct RLS probes use fully valid tenant-B payloads; FK integrity remains a separate probe.
