select pg_temp.assert_true('contradictory evidence relation is preserved',((select count(*) from public.intelligence_outcome_evidence where organization_id=(select value from ctx where key='org_a') and outcome_id=(select value from ctx where key='outcome_a') and relation='contradicts')=1));

select set_config('request.jwt.claim.sub',(select value::text from ctx where key='user_5'),true);
