select pg_temp.assert_true('RH inserts and removes valid own-tenant Outcome',pg_temp.rh_valid_outcome());
select pg_temp.assert_true('RH reads own tenant Bee requests',((select count(*) from public.bee_action_requests where organization_id=(select value from ctx where key='org_a'))=2));
select pg_temp.assert_true('RH cross-tenant Bee request denied by RLS',pg_temp.cross_tenant_bee_rls_probe());
select set_config('request.jwt.claim.sub',(select value::text from ctx where key='user_2'),true);
create or replace function pg_temp.probe_bee_write() returns boolean language plpgsql security invoker as $$ begin begin insert into public.bee_action_requests(organization_id,requester_user_id,action_key,capability_level,risk_level,authorization_requirement,purpose,target_scope_type) values((select value from ctx where key='org_a'),(select value from ctx where key='user_4'),'x','explain','informational','none','x','employee');return true;exception when others then return false;end;end; $$;
create or replace function pg_temp.probe_outcome_write() returns boolean language plpgsql security invoker as $$ begin begin insert into public.intelligence_outcomes(organization_id,outcome_type) values((select value from ctx where key='org_a'),'probe');return true;exception when others then return false;end;end; $$;
select pg_temp.assert_true('diretoria cannot write Bee requests',not pg_temp.probe_bee_write());
select pg_temp.assert_true('diretoria can read Outcomes',((select count(*) from public.intelligence_outcomes where organization_id=(select value from ctx where key='org_a'))=1));
select pg_temp.assert_true('diretoria cannot write Outcomes',not pg_temp.probe_outcome_write());
select pg_temp.assert_true('diretoria cannot read private collaborator request',((select count(*) from public.bee_action_requests where id=(select value from ctx where key='bee_private'))=0));
select set_config('request.jwt.claim.sub',(select value::text from ctx where key='user_3'),true);
select pg_temp.assert_true('gestor cannot write Bee requests',not pg_temp.probe_bee_write());
select pg_temp.assert_true('gestor cannot write Outcomes',not pg_temp.probe_outcome_write());
select pg_temp.assert_true('gestor cannot read private collaborator request',((select count(*) from public.bee_action_requests where id=(select value from ctx where key='bee_private'))=0));
select set_config('request.jwt.claim.sub',(select value::text from ctx where key='user_4'),true);
select pg_temp.assert_true('collaborator cannot write Bee requests',not pg_temp.probe_bee_write());
select pg_temp.assert_true('collaborator cannot write Outcomes',not pg_temp.probe_outcome_write());
select pg_temp.assert_true('requester reads own Bee request',((select count(*) from public.bee_action_requests where id=(select value from ctx where key='bee_private'))=1));
select pg_temp.assert_true('requester cannot read another users request',((select count(*) from public.bee_action_requests where id=(select value from ctx where key='bee_other'))=0));
select pg_temp.assert_true('collaborator cannot read generic request list',((select count(*) from public.bee_action_requests)=1));
rollback;
